import type { CSSProperties, HTMLAttributes, Ref } from "react";
import "./Skeleton.css";

export interface SkeletonProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /** Box width. When omitted, uses the Cmp-token default (100%). */
  width?: CSSProperties["width"];
  /** Box height. When omitted, uses the Cmp-token default (1rem). */
  height?: CSSProperties["height"];
  /**
   * Shape axis. `circle` is for a square placeholder such as an avatar position.
   *
   * @default "rectangle"
   */
  shape?: "rectangle" | "circle";
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

/**
 * Skeleton — loading placeholder.
 *
 * **Accessibility contract: a skeleton is always `aria-hidden`, and the wrapping container owns
 * the loading announcement.** A screen contains multiple skeletons, so if each announces itself
 * the announcements are duplicated — the same division of responsibility as Spinner's
 * `isDecorative` mode. Therefore there is no separate announcement prop — adding one invites a
 * duplicate announcement.
 *
 * Conversely, **if the wrapper does not provide it, nothing is announced.** `SkeletonList` does,
 * but the workshop demos (`App.tsx`, this component's story) do not — they were left that way only
 * because they are not distributed; if product code does not honor this contract, loading is silent.
 */
export function Skeleton({
  width,
  height,
  shape = "rectangle",
  className,
  style,
  ...props
}: SkeletonProps) {
  // Overlay onto style **only the `width`/`height` values that were passed**. Unconditionally
  // spreading `{ ...style, width, height }` writes `width: undefined` when the prop is absent,
  // erasing a consumer-supplied `style={{ width: "50%" }}` (React applies undefined as “no value”).
  const boxStyle: CSSProperties = { ...style };
  if (width !== undefined) boxStyle.width = width;
  if (height !== undefined) boxStyle.height = height;

  return (
    <div
      {...props}
      aria-hidden="true"
      data-shape={shape}
      style={boxStyle}
      className={className ? `sd-skeleton ${className}` : "sd-skeleton"}
    />
  );
}

.sd-skeleton {
  display: block;
  width: var(--sd-skeleton-width);
  height: var(--sd-skeleton-height);
  background: var(--sd-skeleton-background);
  border-radius: var(--sd-skeleton-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  animation: sd-skeleton-pulse var(--sd-skeleton-animation-duration) ease-in-out infinite;
}

/* The pill sentinel, not `50%` — on the square box a circle placeholder actually gets, the two
   are identical, and the token is what Spinner already uses to draw its ring. */
.sd-skeleton[data-shape="circle"] {
  border-radius: var(--sd-skeleton-radius-circle);
  corner-shape: round;
}

@keyframes sd-skeleton-pulse {
  0%,
  100% {
    opacity: var(--sd-skeleton-opacity);
  }

  50% {
    opacity: var(--sd-skeleton-opacity-pulse);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-skeleton {
    animation: none;
  }
}
